'use client';
import Link from 'next/link';
import {useEffect,useState} from 'react';
import {request} from '../../lib/api';
const next:any={PLACED:'ACCEPTED',ACCEPTED:'PREPARING',PREPARING:'READY',READY:'COMPLETED'};
const label:any={PLACED:'ACCEPT ORDER',ACCEPTED:'MARK PREPARING',PREPARING:'MARK READY',READY:'MARK COMPLETED'};
export default function Queue(){const[token,setToken]=useState('');const[id,setId]=useState<string|null>(null);const[orders,setOrders]=useState<any[]>([]);useEffect(()=>{const session=localStorage.getItem('foodcart.vendor')||'';setToken(session);setId(new URLSearchParams(window.location.search).get('id'));if(session)request<any[]>('/api/vendor/orders',{},session).then(setOrders)},[]);async function move(order:any){const saved=await request<any>(`/api/vendor/orders/${order.id}/status`,{method:'PATCH',body:JSON.stringify({status:next[order.status]})},token);setOrders(all=>all.map(x=>x.id===saved.id?saved:x));}const selected=id?orders.find(order=>order.id===id):undefined;const list=selected?[selected]:orders;return <main className="shell bg-[#eef1f5] min-h-screen"><header className="bg-[#3d5366] px-5 py-5 text-white"><div className="mx-auto flex max-w-xl items-center justify-between gap-3"><Link href="/vendor" className="rounded bg-white/15 px-3 py-2 text-xs font-bold">← BACK</Link><b>{selected?`ORDER #${selected.orderNumber}`:'ORDERS'}</b><span>●</span></div></header><div className="mx-auto max-w-xl p-4">{selected&&<Link href="/vendor/orders" className="mb-4 inline-block text-xs font-bold text-[#3d5366]">← ALL ORDERS</Link>}<div className="mb-4 flex items-center justify-between rounded-xl bg-[#bfddf7] p-3"><button>‹</button><b className="text-sm">{selected?'ORDER DETAILS':"TODAY'S ORDERS"}</b><button>›</button></div><div className="space-y-3">{list.map(order=><article key={order.id} className="rounded-lg bg-white p-4 shadow-sm"><div className="flex justify-between"><b className="text-xl">#{order.orderNumber}</b><span className="rounded bg-[#e9f0ff] px-3 py-1 text-[10px] font-bold text-[#285da7]">{order.status.replace('_',' ')}</span></div><div className="mt-3 flex justify-between"><a className="text-sm underline">☎ {order.customerMobile||'Customer'}</a><span className="rounded border px-3 py-1 text-[10px]">{order.type}</span></div><div className="mt-3 text-xs leading-5 text-slate-600">{order.items?.map((item:any)=><p key={item.menuItemId}>{item.quantity}x {item.name} ({item.portion||'FULL'}) · ₹{item.lineTotal}</p>)}</div><div className="mt-4 flex justify-between border-t pt-3"><b>₹{order.total}</b>{label[order.status]&&<button onClick={()=>move(order)} className="rounded bg-[#3d5366] px-5 py-2 text-xs font-bold text-white">{label[order.status]}</button>}</div></article>)}{id&&!selected&&orders.length>0&&<p className="rounded bg-white p-5 text-sm">This order is no longer available.</p>}</div></div></main>}
